CREATE DATABASE IF NOT EXISTS retail_pos CHARACTER SET utf8mb4;
USE retail_pos;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(50) UNIQUE NOT NULL, full_name VARCHAR(100) NOT NULL,
  password_hash VARCHAR(255) NOT NULL, role ENUM('Admin','Cashier') NOT NULL DEFAULT 'Cashier', is_active TINYINT(1) NOT NULL DEFAULT 1,
  failed_attempts INT NOT NULL DEFAULT 0, locked_until DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE categories (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL);
CREATE TABLE products (id INT AUTO_INCREMENT PRIMARY KEY, barcode VARCHAR(50) UNIQUE NOT NULL, name VARCHAR(150) NOT NULL,
  category_id INT NULL, selling_price DECIMAL(10,2) NOT NULL CHECK (selling_price > 0), reorder_level INT NOT NULL DEFAULT 0,
  stock_qty INT NOT NULL DEFAULT 0 CHECK (stock_qty >= 0), is_active TINYINT(1) NOT NULL DEFAULT 1,
  FOREIGN KEY (category_id) REFERENCES categories(id));
CREATE TABLE price_history (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, old_price DECIMAL(10,2), new_price DECIMAL(10,2),
  changed_by INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE stock_movements (id INT AUTO_INCREMENT PRIMARY KEY, product_id INT NOT NULL, type VARCHAR(20) NOT NULL, qty_change INT NOT NULL,
  reason VARCHAR(255), user_id INT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (product_id) REFERENCES products(id));
CREATE TABLE sales (id INT AUTO_INCREMENT PRIMARY KEY, receipt_no VARCHAR(30) UNIQUE NOT NULL, cashier_id INT NOT NULL,
  subtotal DECIMAL(10,2), discount DECIMAL(10,2), vat DECIMAL(10,2), total DECIMAL(10,2), status ENUM('COMPLETED','VOID') DEFAULT 'COMPLETED',
  void_reason VARCHAR(255) NULL, voided_by INT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (cashier_id) REFERENCES users(id));
CREATE TABLE sale_items (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, product_id INT NOT NULL, name VARCHAR(150),
  qty INT NOT NULL, unit_price DECIMAL(10,2), line_total DECIMAL(10,2), FOREIGN KEY (sale_id) REFERENCES sales(id));
CREATE TABLE payments (id INT AUTO_INCREMENT PRIMARY KEY, sale_id INT NOT NULL, method ENUM('CASH','MPESA') NOT NULL,
  amount DECIMAL(10,2), mpesa_code VARCHAR(30) NULL UNIQUE, FOREIGN KEY (sale_id) REFERENCES sales(id));
CREATE TABLE mpesa_requests (checkout_id VARCHAR(60) PRIMARY KEY, phone VARCHAR(15), amount INT, status ENUM('PENDING','PAID','FAILED') DEFAULT 'PENDING',
  mpesa_code VARCHAR(30) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NULL, action VARCHAR(50), details VARCHAR(500),
  ip_address VARCHAR(45), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE settings (skey VARCHAR(50) PRIMARY KEY, sval VARCHAR(255));
